async function main() {
  console.log("Starting database seed...");

  // Clean existing cars and relations
  await prisma.savedCar.deleteMany({});
  await prisma.car.deleteMany({});

  console.log(`Deleted existing records. Inserting ${cars.length} cars...`);

  await prisma.car.createMany({
    data: cars
  });

  console.log(`Database seeded successfully with ${cars.length} cars!`);
}

main()
  .catch((e) => {
    console.error("Seed error:", e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
